package links

import (
	"context"
	"errors"
	"fmt"
	"sort"

	"github.com/containernetworking/plugins/pkg/ns"
	"github.com/vishvananda/netlink"
)

var ErrInterfaceUnowned = errors.New("interface is not marked as containerlab-owned")

// OwnedInterface describes a containerlab-owned interface discovered in a node's
// network namespace.
type OwnedInterface struct {
	Name        string
	Index       int
	PeerIndex   int
	MasterIndex int
	MasterName  string
	Type        string
}

// DiscoverOwnedInterfaces returns containerlab-owned interfaces and the
// netlink metadata needed to verify veth link pairing.
func DiscoverOwnedInterfaces(
	ctx context.Context,
	node Node,
	knownIfaceNames map[string]struct{},
) ([]OwnedInterface, error) {
	return DiscoverOwnedInterfacesFor(ctx, node, ownershipName(node), knownIfaceNames)
}

// DiscoverOwnedInterfacesFor discovers interfaces in node's namespace that
// carry ownership markers for ownerName. Parking nodes use this when the
// namespace and logical node differ.
func DiscoverOwnedInterfacesFor(
	ctx context.Context,
	node Node,
	ownerName string,
	knownIfaceNames map[string]struct{},
) ([]OwnedInterface, error) {
	var interfaces []OwnedInterface

	err := node.ExecFunction(ctx, func(_ ns.NetNS) error {
		links, err := netlink.LinkList()
		if err != nil {
			return err
		}

		for _, link := range links {
			name := link.Attrs().Name
			if name == "lo" || name == "eth0" {
				continue
			}
			if knownIfaceNames != nil {
				if _, known := knownIfaceNames[name]; !known {
					continue
				}
			}
			if !isOwnedBy(link, node, ownerName, name) {
				continue
			}

			info := OwnedInterface{
				Name:        name,
				Index:       link.Attrs().Index,
				MasterIndex: link.Attrs().MasterIndex,
				Type:        link.Type(),
			}
			if info.MasterIndex != 0 {
				master, masterErr := netlink.LinkByIndex(info.MasterIndex)
				if masterErr != nil {
					return fmt.Errorf(
						"failed to discover master for %q: %w",
						name,
						masterErr,
					)
				}
				info.MasterName = master.Attrs().Name
			}
			if info.Type == "veth" {
				veth, ok := link.(*netlink.Veth)
				if !ok {
					veth = &netlink.Veth{LinkAttrs: *link.Attrs()}
				}
				peerIndex, peerErr := netlink.VethPeerIndex(veth)
				if peerErr != nil {
					return fmt.Errorf("failed to discover veth peer for %q: %w", name, peerErr)
				}
				info.PeerIndex = peerIndex
			}

			interfaces = append(interfaces, info)
		}

		return nil
	})
	if err != nil {
		return nil, err
	}

	sort.Slice(interfaces, func(i, j int) bool {
		return interfaces[i].Name < interfaces[j].Name
	})

	return interfaces, nil
}

func DiscoverOwnedInterfaceNames(
	ctx context.Context,
	node Node,
	knownIfaceNames map[string]struct{},
) ([]string, error) {
	interfaces, err := DiscoverOwnedInterfaces(ctx, node, knownIfaceNames)
	if err != nil {
		return nil, err
	}

	ifaceNames := make([]string, 0, len(interfaces))
	for _, iface := range interfaces {
		ifaceNames = append(ifaceNames, iface.Name)
	}
	sort.Strings(ifaceNames)

	return ifaceNames, nil
}

// ValidateOwnedInterface returns an error when an existing interface is not
// owned by the requested logical endpoint. Missing interfaces are valid.
func ValidateOwnedInterface(ctx context.Context, node Node, ifaceName string) error {
	return ValidateOwnedInterfaceFor(ctx, node, ownershipName(node), ifaceName)
}

// ValidateOwnedInterfaceFor validates an interface in node's namespace against
// a possibly different logical owner. Parking nodes use this when the
// interface remains owned by the original node.
func ValidateOwnedInterfaceFor(
	ctx context.Context,
	node Node,
	ownerName string,
	ifaceName string,
) error {
	return node.ExecFunction(ctx, func(_ ns.NetNS) error {
		link, err := netlink.LinkByName(ifaceName)
		if _, notfound := err.(netlink.LinkNotFoundError); notfound {
			return nil
		}
		if err != nil {
			return err
		}
		if isOwnedBy(link, node, ownerName, ifaceName) {
			return nil
		}
		return fmt.Errorf(
			"interface %q on node %q exists but is not containerlab-owned",
			ifaceName,
			node.GetShortName(),
		)
	})
}

func RemoveOwnedInterface(ctx context.Context, node Node, ifaceName string) error {
	if node == nil || ifaceName == "" {
		return nil
	}

	return node.ExecFunction(ctx, func(_ ns.NetNS) error {
		link, err := netlink.LinkByName(ifaceName)
		if _, notfound := err.(netlink.LinkNotFoundError); notfound {
			return removeBridgePort(node, ifaceName)
		}
		if err != nil {
			return err
		}
		if !isOwnedBy(link, node, ownershipName(node), ifaceName) {
			return fmt.Errorf(
				"%w: interface %q on node %q",
				ErrInterfaceUnowned,
				ifaceName,
				node.GetShortName(),
			)
		}

		if err = netlink.LinkDel(link); err != nil {
			return err
		}

		return removeBridgePort(node, ifaceName)
	})
}

// bridgePortDeleter removes a bridge port that can outlive its netdev. OVS ports created for an
// interface name Linux will not accept are named after the random netdev, so deleting the veth
// from the container side leaves the port behind.
type bridgePortDeleter interface {
	DeleteBridgePort(string) error
}

func removeBridgePort(node Node, ifaceName string) error {
	if node == nil || ifaceName == "" {
		return nil
	}

	cleaner, ok := node.(bridgePortDeleter)
	if !ok {
		return nil
	}

	return cleaner.DeleteBridgePort(ifaceName)
}

// isOwnedBy reports whether link carries the ownership marker of the logical
// endpoint ownerName:ifaceName. Interfaces of mgmt-net links deployed by earlier
// releases carry a marker for the bridge name of the mgmt-net link node instead
// of the stable mgmt-net owner name, and are accepted as well.
func isOwnedBy(link netlink.Link, node Node, ownerName, ifaceName string) bool {
	if HasOwnershipAltNameFor(link, ownerName, ifaceName) {
		return true
	}

	if _, ok := node.(*mgmtBridgeLinkNode); ok && ownerName == mgmtNetOwnerName {
		return HasOwnershipAltNameFor(link, node.GetShortName(), ifaceName)
	}

	return false
}

